def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def lcm(a, b):
    if a == 0 or b == 0: return 0
    return abs(a * b) // gcd(a, b)

def get_good_partitions(a):
    n = len(a)
    good = []
    for k in range(1, n):
        L = a[0]
        for i in range(1, k):
            L = lcm(L, a[i])
        G = a[k]
        for i in range(k + 1, n):
            G = gcd(G, a[i])
        if L == G:
            good.append(k)
    return good

# Test some sequences
seq1 = [2, 3, 6, 12, 18, 36]
print(f"Seq1: {seq1}, Good: {get_good_partitions(seq1)}")

